async function addDocument(
  client: AlchemystAI,
  runId: string,
  doc: SeedDoc,
): Promise<AddOutcome> {
  const fileName = `${doc.key}-${runId}.md`;

  // The TypeScript SDK type definition for `metadata` only contains camelCase keys
